import { useCallback, useEffect, useState } from 'react';
import '../App.css';
import Mapa from '../features/mapa/Mapa.jsx';
import { MapActionsProvider } from '../features/mapa/MapContext.jsx';
import Sidebar from '../features/sidebar/SideBar.jsx';
import Cadastro from '../features/cadastro/Cadastro.jsx';

function Home() {
    const [showCadastro, setShowCadastro] = useState(false);
    const [locations, setLocations] = useState([]);

    const openCadastro = () => setShowCadastro(true);
    const closeCadastro = () => setShowCadastro(false);

    const fetchLocations = useCallback(() => {
        fetch('http://localhost:8080/api/local/all')
            .then((res) => res.json())
            .then((data) => setLocations(data))
            .catch((err) => console.error(err));
    }, []);

    useEffect(() => {
        fetchLocations();
    }, [fetchLocations]);

    return (
        <MapActionsProvider>
            <div className="">
                <Mapa locations={locations} />
                <Sidebar onAddLocation={openCadastro} />
                {showCadastro && (
                    <Cadastro onClose={closeCadastro} onSaved={fetchLocations} />
                )}
            </div>
        </MapActionsProvider>
    );
}

export default Home;
